let rec factorial n =
  if n <= 1 then 1
  else n * factorial (n - 1)
(* 尾递归：累加器 *)
let factorial_tail n =
  let rec loop acc k =
    if k <= 1 then acc
    else loop (acc * k) (k - 1)
  in
  loop 1 n
let () =
