let email_re =
  Str.regexp "[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z][A-Za-z]+"

let extract_emails text =
  let rec loop pos acc =
    try
      let _ = Str.search_forward email_re text pos in
      let matched = Str.matched_string text in
      loop (Str.match_end ()) (matched :: acc)
    with Not_found -> List.rev acc
  in
  loop 0 []

let normalize text =
