let sum_list n =
  let rec loop acc i =
    if i > n then acc else loop (acc + i) (i + 1)
  in
  loop 0 1
let sum_array n =
  let arr = Array.init n (fun i -> i + 1) in
  Array.fold_left ( + ) 0 arr
let build_buffer n =
  let buf = Buffer.create (n * 4) in
  for i = 1 to n do
    Buffer.add_string buf (string_of_int i);
    Buffer.add_char buf ','
  done;
  Buffer.contents buf
let time label f =
