let exec db sql =
  match Sqlite3.exec db sql with
  | Sqlite3.R_OK -> ()
  | rc -> failwith (Printf.sprintf "SQL 失败: %s (%s)" sql (Sqlite3.errmsg db))

let query_users db =
  let stmt = Sqlite3.prepare db "SELECT id, name FROM users ORDER BY id" in
  let rec loop acc =
    match Sqlite3.step stmt with
    | Sqlite3.ROW -> loop ((Sqlite3.column_int stmt 0, Sqlite3.column_text stmt 1) :: acc)
    | _ -> List.rev acc
  in
  let rows = loop [] in
  ignore (Sqlite3.finalize stmt);
  rows

