let read_line_fd fd =
  let buf = Buffer.create 128 in
  let chunk = Bytes.create 1 in
  let rec loop () =
    match Unix.read fd chunk 0 1 with
    | 0 -> Buffer.contents buf
    | _ ->
      let c = Bytes.get chunk 0 in
      if c = '\n' then Buffer.contents buf
      else (Buffer.add_char buf c; loop ())
  in
  loop ()
