let valid_username name =
  let len = String.length name in
  len >= 3 && len <= 32
  && String.for_all
       (fun c ->
         (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
         || (c >= '0' && c <= '9') || c = '_')
       name

