let route = function
  | "/" -> (200, "{\"message\":\"hello ocaml\"}")
  | "/health" -> (200, "{\"status\":\"ok\"}")
  | _ -> (404, "{\"error\":\"not found\"}")

let () =
  let sock = Unix.socket Unix.PF_INET Unix.SOCK_STREAM 0 in
  Unix.setsockopt sock Unix.SO_REUSEADDR true;
  Unix.bind sock (Unix.ADDR_INET (Unix.inet_addr_loopback, 8081));
  Unix.listen sock 5;
  Printf.printf "监听 http://127.0.0.1:8081/\n%!";
  let fd, _ = Unix.accept sock in
  let request = input_line (Unix.in_channel_of_descr fd) in
  let path = match String.split_on_char ' ' request with [ _; p; _ ] -> p | _ -> "/" in
  let code, body = route path in
  let resp =
    Printf.sprintf
      "HTTP/1.1 %d %s\r\nContent-Type: application/json\r\nContent-Length: %d\r\nConnection: close\r\n\r\n%s"
      code (if code = 200 then "OK" else "Not Found") (String.length body) body
  in
  ignore (Unix.write_substring fd resp 0 (String.length resp));
  Unix.close fd;
  Unix.close sock

